using MediatR; using PartyNL.Application.Abstractions.Repositories; using PartyNL.Domain.Entities; using PartyNL.Domain.Enums;
namespace PartyNL.Application.Features.Events.Commands.CreateEvent;
public sealed record CreateEventCommand(Guid OrganizerId,Guid LocationId,string Title,string? Description,DateTime StartDate,DateTime EndDate,decimal Price,int Capacity,int MinimumAge,EventVisibility Visibility,EventStatus Status,string? CoverImageUrl):IRequest<CreateEventResponse>;public sealed record CreateEventResponse(Guid Id,Guid OrganizerId,Guid LocationId,string Title,string? Description,DateTime StartDate,DateTime EndDate,decimal Price,int Capacity,int MinimumAge,EventVisibility Visibility,EventStatus Status,string? CoverImageUrl);
public sealed class CreateEventHandler(IEventRepository repository):IRequestHandler<CreateEventCommand,CreateEventResponse>{public async Task<CreateEventResponse> Handle(CreateEventCommand request,CancellationToken cancellationToken){var e=new Event{OrganizerId=request.OrganizerId,LocationId=request.LocationId,Title=request.Title,Description=request.Description,StartDate=request.StartDate,EndDate=request.EndDate,Price=request.Price,Capacity=request.Capacity,MinimumAge=request.MinimumAge,Visibility=request.Visibility,Status=request.Status,CoverImageUrl=request.CoverImageUrl};await repository.AddAsync(e);return Map(e);}private static CreateEventResponse Map(Event e)=>new(e.Id,e.OrganizerId,e.LocationId,e.Title,e.Description,e.StartDate,e.EndDate,e.Price,e.Capacity,e.MinimumAge,e.Visibility,e.Status,e.CoverImageUrl);}